import{z as B,x as d,o as E,c as A,q as n,j as o,D as t,d as e,s as r,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"分页 KV 的内核接口","description":"","frontmatter":{"title":"分页 KV 的内核接口","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-paged-kv-kernel.md","filePath":"llm/ak-paged-kv-kernel.md","lastUpdated":1791063341000}'),m={name:"llm/ak-paged-kv-kernel.md"};function p(h,a,c,f,k,D){const i=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=n('<h1 id="分页-kv-的内核接口" tabindex="-1">分页 KV 的内核接口 <a class="header-anchor" href="#分页-kv-的内核接口" aria-label="Permalink to &quot;分页 KV 的内核接口&quot;">​</a></h1><div class="epigraph"><p>内核不再拿到一块连续显存，而拿到一张页表；地址翻译进了热路径，softmax 一个字没变。</p><footer>—— 据 Kwon et al., PagedAttention, SOSP 2023 整理</footer></div><p><a href="/llm/ak-gqa-mqa-kernels">上一课</a>把头的共享落进核内。本课处理第二个变体，动的是地址这一维。<a href="/llm/paged-attention">PagedAttention</a> 在系统侧定过页与页表、碎片与引用计数，<a href="/llm/vllm-paged">vLLM 与 PagedAttention</a> 定过它与调度器的分工；本课站在内核接口这一侧：当 KV 不再连续、长度不再齐整，tiling 循环怎么改，地址翻译怎么不拖垮热路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统内核假设 K、V 是 \\([\\mathrm{batch},h,n,d]\\) 的连续张量，元素地址是下标的仿射函数，编译器与硬件都按这个假设做合并访问。服务里每个请求的 KV 散布在物理页上——页表与块大小见<a href="/llm/paged-kv-block-size">分页 KV 与块大小</a>，而且批内长度各异。缺口因此有两个：其一，tiling 的外层循环本来扫逻辑位置，现在每一步要先经块表翻成物理地址，翻译若掉出热路径、变成一次回读元数据的往返，内核就慢得不讲道理；其二，变长带来的尾块要按真实长度掩掉，掩码必须与同一循环咬合。</p><p><span class="marginnote">直觉类比：连续 KV 像把书按顺序码满一整面墙，取第 k 本直接算位置；分页 KV 像书分散在图书馆各层书架——取书前先查索引卡（块表）知道在哪架，再在架内按位置拿。多了一步查表，换来的是空间能见缝插针地用。</span></p><h3 id="接口三件套" tabindex="-1">接口三件套 <a class="header-anchor" href="#接口三件套" aria-label="Permalink to &quot;接口三件套&quot;">​</a></h3><p>内核收到的不再是张量，而是三样东西：块表 <code>block_tables</code>（每请求的逻辑块号到物理块号）、长度表 <code>seq_lens</code>（每个请求的真实 token 数）、以及页大小的约定。数学没有任何变化：softmax 仍在完整合法前缀上精确计算，变的只是取数的路径。</p>',8)),(E(),o(s,null,{default:t(()=>[r(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20OLD%5B%22%E6%97%A7%E6%8E%A5%E5%8F%A3%3A%20%E8%BF%9E%E7%BB%AD%E5%BC%A0%E9%87%8F%20batch%C3%97h%C3%97n%C3%97d%22%5D%20--%3E%20O1%5B%22%E5%9C%B0%E5%9D%80%20%3D%20%E4%B8%8B%E6%A0%87%E7%9A%84%E4%BB%BF%E5%B0%84%E5%87%BD%E6%95%B0%22%5D%0A%20%20NEW%5B%22%E6%96%B0%E6%8E%A5%E5%8F%A3%E4%B8%89%E4%BB%B6%E5%A5%97%22%5D%20--%3E%20N1%5B%22block_tables%3A%20%E9%80%BB%E8%BE%91%E5%9D%97%20%E2%86%92%20%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%0A%20%20NEW%20--%3E%20N2%5B%22seq_lens%3A%20%E6%AF%8F%E8%AF%B7%E6%B1%82%E7%9C%9F%E5%AE%9E%E9%95%BF%E5%BA%A6%22%5D%0A%20%20NEW%20--%3E%20N3%5B%22%E9%A1%B5%E5%A4%A7%E5%B0%8F%E7%BA%A6%E5%AE%9A%22%5D%0A%20%20N1%20--%3E%20K%5B%22softmax%20%E6%95%B0%E5%AD%A6%E4%B8%8D%E5%8F%98%2C%20%E5%8F%AA%E6%9C%89%E5%8F%96%E6%95%B0%E8%B7%AF%E5%BE%84%E5%8F%98%22%5D%0A%20%20N2%20--%3E%20K%0A%20%20N3%20--%3E%20K%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"方法",tabindex:"-1"},[e("方法 "),l("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),a[4]||(a[4]=l("p",null,[e("循环改成两级译址。外层按逻辑块 \\(j\\) 从 \\(0\\) 扫到 \\(\\lceil n/B\\rceil\\)：查块表得物理页号，页内偏移乘 \\(d\\) 得元素地址；页内连续，所以 warp 的合并访问保得住。尾块按 "),l("code",null,"seq_lens"),e(" 掩掉越界行，掩码落在线上 softmax 之前，与因果掩码按位或。前填侧同一条路径反向走：新算出的 K、V 按当前页表写进零散页，写出粒度也是页。页大小与 tile 对齐时，每个 tile 恰好查一次表；错开时，一个 tile 跨两页，行级译址把合并访问拆碎。")],-1)),a[5]||(a[5]=l("p",null,[l("span",{class:"marginnote"},[e("常见误区：尾块的「多余行」不是可以顺手一起算的部分——批内各请求长度不一，页内最后几个槽位是未初始化的。不按 "),l("code",null,"seq_lens"),e(" 掩掉，softmax 会把页里的垃圾当合法 KV 算进去，输出悄悄错掉，还不会报任何错。")])],-1)),(E(),o(s,null,{default:t(()=>[r(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E9%80%BB%E8%BE%91%20KV%20%E5%9D%97%20j%22%5D%20--%3E%20T%5B%22%E6%9F%A5%20block_tables%20%E5%BE%97%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%0A%20%20T%20--%3E%20M%5B%22%E9%A1%B5%E5%86%85%E5%81%8F%E7%A7%BB%20%C3%97%20d%EF%BC%9A%E8%BF%9E%E7%BB%AD%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20M%20--%3E%20C%7B%22j%20%E6%98%AF%E5%B0%BE%E5%9D%97%3F%22%7D%0A%20%20C%20--%3E%7C%E6%98%AF%7C%20MSK%5B%22%E6%8C%89%20seq_lens%20%E6%8E%A9%E8%B6%8A%E7%95%8C%E8%A1%8C%22%5D%0A%20%20C%20--%3E%7C%E5%90%A6%7C%20F%5B%22%E6%95%B4%E5%9D%97%E8%BF%9B%E5%9C%A8%E7%BA%BF%20softmax%22%5D%0A%20%20MSK%20--%3E%20F%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么页大小要与 KV tile 对齐：页与 tile 同大（工程上页取 16 的倍数、tile 取 64 或 128），查表开销摊到整个 tile，每 tile 一次表读、一次地址基址更新；页太小，查表次数涨到每 tile 多次，页太碎则每行都要单独译址。两头的账在<a href="/llm/paged-kv-block-size">分页 KV 与块大小</a>里有解析式：内部碎片期望约 \\(B/2\\) 个槽位，查找约 \\(\\lceil n/B\\rceil\\) 次——容量省了，内核的译址成本涨了，取点是工程决定。错法里最危险的一种是「事后修补」：内核仍按连续写，调度器再来挪数据补页表——不仅多一遍全量搬运，还在挪动的窗口里读到大面积脏数据，输出错得悄无声息。地址翻译属于内核合同的一部分，写进接口，不写在补丁里。</p><p><span class="marginnote">数字实例：页与 tile 对齐时，128 行的 tile 只查 1 次表；错开到行级译址，同样 128 行要查 128 次——对齐把译址开销摊薄了上百倍。页取大又会让每个请求平均浪费约 \\(B/2\\) 个槽位（页 16 时约 8 槽），两头取点是工程权衡。</span></p><p><span class="marginnote">vLLM 默认块 16 token：内部碎片期望约 8 槽/请求；\\(n=2048\\) 时每请求约 128 次查表——对齐 tile 后每次查表是一次 smem 内的基址更新，不是一次 HBM 往返，这笔账才能算平。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的页表服务精确注意力：跳过的块、共享的页都仍按页粒度进循环。引用计数与前缀共享的写时复制是调度器与 KV 管理的事，内核只认页号合法。KV 的压缩与驱逐不在本课，那是 KV 管理课程的题目。与上一课的组映射是正交坐标：头共享决定读哪一套 KV，页表决定那一套住在哪，两者叠在同一个循环里，谁也不替代谁。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核接口从连续张量换成块表加长度表，softmax 数学不变，地址路径全变。</li><li>两级译址：逻辑块查表、页内仿射寻址；页内连续是合并访问的底线。</li><li>页大小与 tile 对齐，查表摊薄成每 tile 一次；错开就把译址成本放大到行级。</li><li>尾块掩码与因果掩码在同一个循环里咬合，变长不是特例而是常态。</li><li>事后挪数据补页表是错的：翻译必须写进接口，不能写在补丁里。</li><li>出处：Kwon et al., <em>Efficient Memory Management for LLM Serving with PagedAttention</em>, SOSP 2023。</li></ul>',8))])}const K=B(m,[["render",p]]);export{u as __pageData,K as default};
